const item = items[0].json;
const publishedDate = new Date(item.isoDate || item.pubDate);
const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);

// Only process items from last 24 hours
if (publishedDate < oneDayAgo) {
  return [];
}

// Estimate word count from content or contentSnippet
const content = item['content:encoded'] || item.content || item.contentSnippet || '';
const wordCount = content.split(/\s+/).length;

// Determine content type based on characteristics
let contentType = 'article';
if (item.categories?.some(c => c.toLowerCase().includes('blog'))) {
  contentType = 'blog';
}

// Extract clean text description
const description = (item.contentSnippet || item.description || '')
  .replace(/<[^>]*>/g, '')
  .substring(0, 500);

return [{
  json: {
    title: item.title,
    description: description,
    url: item.link,
    author: item.creator || item['dc:creator'] || 'Unknown',
    published_at: publishedDate.toISOString(),
    content_type: contentType,
    word_count: Math.min(wordCount, 10000),
    thumbnail_url: item.enclosure?.url || item['media:thumbnail']?.$?.url || null,
    categories: item.categories || [],
    feed_url: $json["source_url"]
  }
}];

const article = items[0].json;

// Calculate quality score
let qualityScore = 0.6; // Base score

// Adjust based on word count (prefer 500-2000 words)
if (article.word_count >= 500 && article.word_count <= 2000) {
  qualityScore += 0.2;
} else if (article.word_count > 2000) {
  qualityScore += 0.1;
}

// Has author
if (article.author && article.author !== 'Unknown') {
  qualityScore += 0.1;
}

// Has thumbnail
if (article.thumbnail_url) {
  qualityScore += 0.05;
}

// Has categories
if (article.categories.length > 0) {
  qualityScore += 0.05;
}

qualityScore = Math.min(qualityScore, 1.0);

const metadata = {
  feed_url: article.feed_url,
  categories: article.categories,
  original_url: article.url,
  estimated_read_time: Math.ceil(article.word_count / 200) // 200 wpm
};

return {
  json: {
    external_id: null,
    content_type: article.content_type,
    source: 'rss',
    title: article.title,
    description: article.description,
    url: article.url,
    thumbnail_url: article.thumbnail_url,
    author: article.author,
    published_at: article.published_at,
    word_count: article.word_count,
    quality_score: qualityScore.toFixed(2),
    popularity_score: 0,
    metadata: metadata
  }
};
